708    protected def normConjunct(x: Iterable[Type])(implicit history: Set[hType]): List[Type] = {
709      // A closed trait is replaced by the types its comprises clause lists that no other
710      // conjunct excludes, only where that conjunct names no type or inference variable:
711      // over a variable the union would be split by the union rule before the variable's
712      // bound is read, and a solution that holds only of the union as a whole is lost.
713      def excludedListed(c: Type) =
714        x.exists(z => getVarTypes(z).isEmpty && !hasInferenceVars(z) && dExc(z, c))
715      val cc = x.map(y => (y, y.isInstanceOf[TraitType] &&
716                              comprisesClause(y.asInstanceOf[TraitType]).exists(excludedListed))).toList
717      if (cc.exists(_._2))
718        cc.map(z => { val (y, p) = z;
719                      if (p) makeUnionType(comprisesClause(y.asInstanceOf[TraitType]).toList.flatMap(c => if (excludedListed(c)) None else Some(c)))
720                      else y })
721      else if (x.exists(y => x.exists(z => dExc(y, z))))
722        List(BOTTOM)
723      else {
724        val ds = x.foldLeft(List[Type]())((l, a) => {
725          val l2 = l.filter(x => !isTrue(sub(a, x)))
726          l2 ++ (if (l2.exists(x => isTrue(sub(x, a)))) Nil else List(a))
727        })
728        val es = ds.map(_ match {
729          case t:TupleType => Left(t)
730          case s => Right(s)
731        })
732        val (ts, ss) = (for (Left(x) <- es) yield x, for (Right(x) <- es) yield x)
733        ss ++ normTuples(ts)
734      }
735    }

