import java.nio.file.*;
import java.util.*;
import jdk.jfr.consumer.*;

// java JfrAgg.java <file.jfr> <mode: self|incl|callers|callees|lines> [method-substring] [onstack-substring] [top N]
public class JfrAgg {
    static String name(RecordedFrame f) {
        RecordedMethod m = f.getMethod();
        return m.getType().getName() + "." + m.getName();
    }
    public static void main(String[] a) throws Exception {
        Path p = Paths.get(a[0]);
        String mode = a[1];
        String target = a.length > 2 ? a[2] : "";
        String onstack = a.length > 3 ? a[3] : "";
        int top = a.length > 4 ? Integer.parseInt(a[4]) : 40;
        Map<String, Long> counts = new HashMap<>();
        long total = 0, kept = 0;
        try (RecordingFile rf = new RecordingFile(p)) {
            while (rf.hasMoreEvents()) {
                RecordedEvent e = rf.readEvent();
                if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
                RecordedStackTrace st = e.getStackTrace();
                if (st == null) continue;
                total++;
                List<RecordedFrame> fs = st.getFrames();
                if (!onstack.isEmpty()) {
                    boolean found = false;
                    for (RecordedFrame f : fs) if (name(f).contains(onstack)) { found = true; break; }
                    if (!found) continue;
                }
                kept++;
                if (fs.isEmpty()) continue;
                switch (mode) {
                    case "self": counts.merge(name(fs.get(0)) + " [" + fs.get(0).getType() + "]", 1L, Long::sum); break;
                    case "incl": {
                        Set<String> seen = new HashSet<>();
                        for (RecordedFrame f : fs) seen.add(name(f));
                        for (String s : seen) counts.merge(s, 1L, Long::sum);
                        break;
                    }
                    case "lines": {
                        Set<String> seen = new HashSet<>();
                        for (RecordedFrame f : fs) if (name(f).contains(target)) seen.add(name(f) + ":" + f.getLineNumber());
                        for (String s : seen) counts.merge(s, 1L, Long::sum);
                        break;
                    }
                    case "callers": case "callees": {
                        Set<String> seen = new HashSet<>();
                        for (int i = 0; i < fs.size(); i++) {
                            if (!name(fs.get(i)).contains(target)) continue;
                            int j = mode.equals("callers") ? i + 1 : i - 1;
                            if (j < 0 || j >= fs.size()) { seen.add("<none>"); continue; }
                            seen.add(name(fs.get(j)) + ":" + fs.get(mode.equals("callers") ? j : i).getLineNumber());
                        }
                        for (String s : seen) counts.merge(s, 1L, Long::sum);
                        break;
                    }
                }
            }
        }
        System.out.println("samples total=" + total + " kept=" + kept);
        final long k = kept;
        counts.entrySet().stream().sorted((x, y) -> Long.compare(y.getValue(), x.getValue())).limit(top)
            .forEach(en -> System.out.printf("%8d %5.1f%%  %s%n", en.getValue(), 100.0 * en.getValue() / Math.max(1, k), en.getKey()));
    }
}

